-- A person's statements: how many have been taken, and the last one's due-total (null when it was
-- n/a, or when none has been taken) and date (the sheet's today when it was taken).
ALTER TABLE person ADD COLUMN statement_count INT DEFAULT 0 NOT NULL;
ALTER TABLE person ADD COLUMN stated_total DECIMAL(14,2);
ALTER TABLE person ADD COLUMN statement_date DATE;
-- A claim that counted at its person's last statement is bound (`stated`) to the figure it had
-- then (`stated_due`, null when that was n/a): it shows and totals that figure, whatever later
-- rates or grades would make it, until the next statement rebinds or unbinds it. A settled
-- claim's fixed `due` still comes first.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(14,2);
-- Every statement taken for a person, numbered from 1 in the order taken (`seq`), with its
-- due-total (null when n/a) and date: so cancelling the last one can show the one before it.
-- The person's statement_count, stated_total and statement_date stay the last one's.
CREATE TABLE person_statement (
    id          BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id    VARCHAR(200) NOT NULL,
    person_id   BIGINT       NOT NULL REFERENCES person (id),
    seq         INT          NOT NULL,
    stated_total DECIMAL(14,2),
    statement_date DATE      NOT NULL
);
CREATE INDEX person_statement_person ON person_statement (person_id, seq);
-- A statement taken before this was kept is known only as the last one.
INSERT INTO person_statement (sheet_id, person_id, seq, stated_total, statement_date)
    SELECT sheet_id, id, statement_count, stated_total, statement_date FROM person
    WHERE statement_count > 0 AND statement_date IS NOT NULL;
-- Whether a steward has waived the claim's late charge: a waived claim bears none from then on.
ALTER TABLE public.claim ADD COLUMN waived BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE asof.claim ADD COLUMN waived BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE asof_hist.claim ADD COLUMN waived BOOLEAN DEFAULT FALSE NOT NULL;
-- The history trigger keeps the column list it was created with: create it again to see the new one.
DROP TRIGGER public.claim_history;
CREATE TRIGGER claim_history AFTER INSERT, UPDATE, DELETE ON public.claim FOR EACH ROW CALL 'net.officefloor.hq.app.sheet.History';
package net.officefloor.hq.app.person;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A statement taken for a person: their due-total then (null when n/a) and how many of their
 *  claims counted, by whom, and the date it was taken as of (null: taken now). */
public record Statement(BigDecimal dueTotal, int claims, String user, LocalDate asOf) {

    public Statement(BigDecimal dueTotal, int claims, String user) {
        this(dueTotal, claims, user, null);
    }
}
package net.officefloor.hq.app.person;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.HashMap;
import java.util.Map;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.claim.Figures;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.sheet.AsOf;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Takes the person's statement: their due-total now, the sum of their counting claims' figures
 *  with any late charges, each at least the floor (n/a when there is no rate today and none has a figure), at most the sheet's cap, dated the sheet's today. Every claim
 *  of theirs that counts (not an OPEN one dated within one of their holds) is bound to its rate figure now, without its late charge or the floor; every other one is unbound.
 *  Taken as of a date (on or before the sheet's today), all of it is worked out on the sheet as it
 *  stood at the end of that date (see {@link AsOf}): the claims that counted then are bound to their
 *  figures then, and the statement is dated that date. Refused: a date after the sheet's today, or
 *  one the person was not yet on the sheet. */
public class TakeStatement {
    public void take(@Val StatementRequest request, @Val Person person, Claims claims, Figures figures,
            Rates rates, Sheets sheets, Settings settings, People people, AsOf asOf, Out<Statement> statement)
            throws InvalidSheetRequestException {
        LocalDate date = asOfDate(request);
        String sheetId = person.getSheetId();
        if (date != null && date.isAfter(sheets.today(sheetId))) {
            throw new InvalidSheetRequestException("A statement cannot be taken as of a date after the sheet's today");
        }
        Person locked = people.lock(sheetId, person.getId());
        person.setStatementCount(locked.getStatementCount());
        Taken taken = date == null ? work(person, claims, figures, rates, sheets, settings)
                : asOf.at(sheetId, date, () -> {
                    Person then = people.find(sheetId, person.getId());
                    return then == null ? null : work(then, claims, figures, rates, sheets, settings);
                });
        if (taken == null) {
            throw new InvalidSheetRequestException("This person was not on the sheet on " + date);
        }
        for (Claim claim : claims.ofPerson(sheetId, person.getId())) {
            boolean bound = taken.bound().containsKey(claim.getId());
            claim.setStated(bound);
            claim.setStatedDue(bound ? taken.bound().get(claim.getId()) : null);
            claims.save(claim);
        }
        person.setStatementCount(person.getStatementCount() + 1);
        person.setStatedTotal(taken.dueTotal());
        person.setStatementDate(taken.date());
        people.saveStatement(person);
        statement.set(new Statement(taken.dueTotal(), taken.bound().size(), request.user(), date));
    }

    /** The statement of the person as the sheet stands (live, or as of a date): the figure each
     *  counting claim is bound to, by id, and their due-total, dated the sheet's today. */
    private static Taken work(Person person, Claims claims, Figures figures, Rates rates, Sheets sheets,
            Settings settings) {
        String sheetId = person.getSheetId();
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean any = false;
        Map<Long, BigDecimal> bound = new HashMap<>();
        for (Claim claim : claims.ofPerson(sheetId, person.getId())) {
            if (person.counts(claim)) {
                // The statement binds the rate figure; the late charge and floor on top keep following today.
                bound.put(claim.getId(), figures.figure(claim, person.gradeOn(claim.getDate())));
                BigDecimal figure = figures.due(claim, person.gradeOn(claim.getDate()));
                if (figure != null) {
                    total = total.add(figure);
                    any = true;
                }
            }
        }
        LocalDate today = sheets.today(sheetId);
        BigDecimal dueTotal = !any && rates.pct(sheetId, person.gradeOn(today), today) == null ? null
                : settings.capped(sheetId, total);
        return new Taken(bound, dueTotal, today);
    }

    /** The date the statement is taken as of; null when none was given. */
    private static LocalDate asOfDate(StatementRequest request) throws InvalidSheetRequestException {
        String text = request.asOf();
        if (text == null || text.isBlank()) return null;
        try {
            return LocalDate.parse(text.trim());
        } catch (DateTimeParseException e) {
            throw new InvalidSheetRequestException("Not a date: " + text);
        }
    }

    private record Taken(Map<Long, BigDecimal> bound, BigDecimal dueTotal, LocalDate date) {
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.settings.Role;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** A steward cancels the person's last statement. The claims it bound (those bound now: each
 *  statement rebinds or unbinds every claim of the person) become live again — a figure an earlier
 *  statement bound is not restored. The count goes down by one and the person shows the statement
 *  before it, or none. Refused: anyone but a steward, a person with no statement. Read afresh and
 *  locked, so it happens one after another with a statement taken at once. */
public class CancelStatement {
    public void cancel(@PathVariable("sheetId") String sheetId, @PathVariable("personId") long personId,
            @Val StatementRequest request, People people, Claims claims, Settings settings,
            Out<Person> personOut, Out<Statement> statement)
            throws PersonNotFoundException, InvalidSheetRequestException {
        if (settings.role(sheetId, request.user()) != Role.STEWARD) {
            throw new InvalidSheetRequestException("Only a steward can cancel a statement");
        }
        Person person = people.lock(sheetId, personId);
        if (person == null) throw new PersonNotFoundException(personId);
        if (person.getStatementCount() <= 0) {
            throw new InvalidSheetRequestException("This person has no statement to cancel");
        }
        Statement cancelled = new Statement(person.getStatedTotal(), 0, request.user());
        claims.unbind(sheetId, personId);
        people.cancelStatement(person);
        personOut.set(person);
        statement.set(cancelled);
    }
}
